<template><CrudShell title="Quản lý landing banner" :loading="loading" :error="error" @create="openCreate" @reload="load"><template #form v-if="editing"><form class="grid gap-3 rounded-3xl border bg-white p-4 md:grid-cols-3" @submit.prevent="save"><input v-model="form.title" class="rounded-xl border p-3" placeholder="Title"><input v-model="form.subtitle" class="rounded-xl border p-3" placeholder="Subtitle"><input v-model="form.linkUrl" class="rounded-xl border p-3" placeholder="Link URL"><input v-model="form.fileId" class="rounded-xl border p-3" placeholder="File ID"><select v-model="form.status" class="rounded-xl border p-3"><option>ACTIVE</option><option>INACTIVE</option></select><input v-model.number="form.sortOrder" class="rounded-xl border p-3" placeholder="Sort"><input v-model="form.startsAt" class="rounded-xl border p-3" placeholder="Starts at"><input v-model="form.endsAt" class="rounded-xl border p-3" placeholder="Ends at"><div class="md:col-span-3"><FileUpload v-model="uploaded" scope="admin" accept="image/*" title="Upload banner image" @uploaded="(file) => form.fileId = String(file.fileId)" /></div><div class="flex gap-2 md:col-span-3"><button class="rounded-xl bg-slate-950 px-4 py-2 font-bold text-white">Save</button><button type="button" class="rounded-xl border px-4 py-2" @click="editing = null">Cancel</button></div></form></template><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Title</th><th>Status</th><th>Sort</th><th>Link</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-b"><td class="p-3 font-bold">{{ row.title }}</td><td>{{ row.status }}</td><td>{{ row.sortOrder }}</td><td>{{ row.linkUrl }}</td><td class="space-x-2 text-right"><button class="font-bold" @click="openEdit(row)">Edit</button><button class="font-bold text-red-600" @click="remove(row.id)">Delete</button></td></tr></tbody></table></CrudShell></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import CrudShell from '@/pages/admin/CrudShell.vue'; import FileUpload from '@/components/common/FileUpload.vue'; import { bannerApi } from '@/modules/content/banner/api'; import { getErrorMessage } from '@/modules/shared/hooks'; import type { LandingBanner, LandingBannerPayload } from '@/modules/content/banner/types'; import type { UploadedFile } from '@/services/file.service'
const rows = ref<LandingBanner[]>([]); const loading = ref(false); const error = ref(''); const editing = ref<LandingBanner | 'new' | null>(null); const uploaded = ref<UploadedFile | null>(null); const form = reactive<LandingBannerPayload>({ title: '', subtitle: '', linkUrl: '', fileId: '', status: 'ACTIVE', sortOrder: 0, startsAt: '', endsAt: '' })
function fill(r?: LandingBanner) { Object.assign(form, { title: r?.title || '', subtitle: r?.subtitle || '', linkUrl: r?.linkUrl || '', fileId: r?.fileId || '', status: r?.status || 'ACTIVE', sortOrder: r?.sortOrder || 0, startsAt: r?.startsAt || '', endsAt: r?.endsAt || '' }) } function openCreate() { editing.value = 'new'; fill() } function openEdit(r: LandingBanner) { editing.value = r; fill(r) } async function load() { loading.value = true; try { rows.value = (await bannerApi.adminList({ limit: 50 })).items } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } } async function save() { try { if (editing.value === 'new') await bannerApi.create(form); else if (editing.value) await bannerApi.update(editing.value.id, form); editing.value = null; await load() } catch (e) { error.value = getErrorMessage(e) } } async function remove(id: string) { if (!confirm('Delete banner?')) return; await bannerApi.remove(id); await load() } onMounted(load)
</script>
